package com.hiretrack.entity;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="tasks")public class Task{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(nullable=false)private String title;@Column(length=2000)private String description;private LocalDateTime dueDate;private boolean completed=false;public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public LocalDateTime getDueDate(){return dueDate;}public void setDueDate(LocalDateTime v){dueDate=v;}public boolean isCompleted(){return completed;}public void setCompleted(boolean v){completed=v;}}